import { cn } from '@cascivo/core/pure'
import type { CSSProperties, HTMLAttributes } from 'react'
import styles from './grid.module.css'
import type { SpaceStep } from '@cascivo/core'

/** A scalar value, or a per-breakpoint object keyed by the canonical scale. */
export type Responsive<T> = T | Partial<Record<'base' | 'sm' | 'md' | 'lg' | 'xl', T>>

function isResponsive<T>(value: Responsive<T>): value is Partial<Record<string, T>> {
  return typeof value === 'object' && value !== null
}

/**
 * Map a responsive number onto CSS custom properties. Scalar → `<prefix>` only
 * (unchanged back-compat). Object → `<prefix>` for `base` plus `<prefix>-<bp>`
 * per declared tier; omitted tiers fall back through the CSS var chain.
 */
function responsiveVars(prefix: string, value: Responsive<number> | undefined): CSSProperties {
  if (value === undefined) return {}
  if (!isResponsive(value)) return { [prefix]: String(value) } as CSSProperties
  const out: Record<string, string> = {}
  if (value.base !== undefined) out[prefix] = String(value.base)
  for (const bp of ['sm', 'md', 'lg', 'xl'] as const) {
    const v = value[bp]
    if (v !== undefined) out[`${prefix}-${bp}`] = String(v)
  }
  return out as CSSProperties
}

/** Grid track alignment keyword (maps directly to `align-items` / `justify-items`). */
export type GridAlign = 'start' | 'center' | 'end' | 'stretch'

export interface GridProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * Column count — a number, or a per-breakpoint object (base/sm/md/lg/xl) for responsive
   * columns
   *
   * @defaultValue `12`
   * @see the component manifest
   */
  cols?: Responsive<number>
  /**
   * Spacing token step. Maps to the --cascivo-space-* scale, which intentionally skips
   * 7/9/11 — use 6 or 8.
   *
   * @defaultValue `4`
   * @see the component manifest
   */
  gap?: SpaceStep
  /** Block-axis alignment of items within their cells (`align-items`). Defaults to `stretch`. */
  align?: GridAlign
  /** Inline-axis alignment of items within their cells (`justify-items`). Defaults to `stretch`. */
  justify?: GridAlign
  /**
   * Align the internal bands of adjacent children via CSS subgrid — every CardHeader in a
   * row shares one row track, every CardContent the next, every CardFooter the last. Where
   * subgrid is unsupported the grid renders as it does without this prop.
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  alignRows?: boolean
}

export function Grid({
  cols = 12,
  gap = 4,
  align,
  justify,
  alignRows = false,
  className,
  style,
  children,
  ...props
}: GridProps) {
  // The outer element establishes the query container (`container-type`); the inner
  // `.grid` hosts the `@container` column rules, which resolve against that outer
  // element. An element can never be its own query container, so a self-contained
  // Grid needs this wrapper — without it responsive `cols` silently collapse to the
  // base count wherever no ancestor happens to establish containment.
  return (
    <div
      className={cn(styles['grid-container'], className)}
      style={{
        ...responsiveVars('--_grid-cols', cols),
        ['--_grid-gap' as string]: `var(--cascivo-space-${gap})`,
        ...(align ? { ['--_grid-align' as string]: align } : {}),
        ...(justify ? { ['--_grid-justify' as string]: justify } : {}),
        ...style,
      }}
      {...props}
    >
      <div
        className={styles['grid']}
        data-responsive={isResponsive(cols) ? '' : undefined}
        data-align-rows={alignRows ? '' : undefined}
      >
        {children}
      </div>
    </div>
  )
}

export interface GridItemProps extends HTMLAttributes<HTMLDivElement> {
  /** Column span. A number, or `{ base, sm, md, lg, xl }` for responsive spans. */
  span?: Responsive<number>
}

export function GridItem({ span, className, style, ...props }: GridItemProps) {
  const responsive = span !== undefined && isResponsive(span)
  return (
    <div
      className={cn(styles['grid-item'], className)}
      data-responsive={responsive ? '' : undefined}
      style={{ ...responsiveVars('--_span', span), ...style }}
      {...props}
    />
  )
}

@layer cascivo.component {
  /* Establishes the query container the `.grid` column rules resolve against, and a
     single implicit cell so `.grid` fills it on both axes (preserving the pre-wrapper
     behaviour where the grid element was the layout box). */
  .grid-container {
    display: grid;
    container-type: inline-size;
  }

  .grid {
    display: grid;
    grid-template-columns: repeat(var(--_grid-cols, 12), minmax(0, 1fr));
    gap: var(--_grid-gap, var(--cascivo-space-4));
    align-items: var(--_grid-align, stretch);
    justify-items: var(--_grid-justify, stretch);
    min-inline-size: 0;
    container-type: inline-size;

    /* Scalar mode — unchanged back-compat collapse to a single column on a narrow slot. */
    &:not([data-responsive]) {
      @container (max-width: 40rem) {
        grid-template-columns: 1fr;
      }
    }

    /* Responsive mode — each tier falls back to the previous declared tier. */
    &[data-responsive] {
      @container (min-width: 30rem) {
        grid-template-columns: repeat(var(--_grid-cols-sm, var(--_grid-cols, 12)), minmax(0, 1fr));
      }
      @container (min-width: 40rem) {
        grid-template-columns: repeat(
          var(--_grid-cols-md, var(--_grid-cols-sm, var(--_grid-cols, 12))),
          minmax(0, 1fr)
        );
      }
      @container (min-width: 64rem) {
        grid-template-columns: repeat(
          var(--_grid-cols-lg, var(--_grid-cols-md, var(--_grid-cols-sm, var(--_grid-cols, 12)))),
          minmax(0, 1fr)
        );
      }
      @container (min-width: 80rem) {
        grid-template-columns: repeat(
          var(
            --_grid-cols-xl,
            var(--_grid-cols-lg, var(--_grid-cols-md, var(--_grid-cols-sm, var(--_grid-cols, 12))))
          ),
          minmax(0, 1fr)
        );
      }
    }
  }

  /*
    Row-band alignment (`alignRows`). Two cards side by side fill the row because
    `.grid-item` stretches — but their internal bands land wherever their own content puts
    them, so a one-line title sits beside a two-line title and every footer below is off by
    a row. That is the single most-reported card-grid defect and CSS had no answer before
    subgrid.

    Each direct child spans the same three implicit row tracks and adopts them with
    `grid-template-rows: subgrid`, so band N of every card in a row resolves to ONE shared
    track sized to the tallest occupant. Three because that is Card's published anatomy —
    header, content, footer. A card with only two of them leaves the third track empty and
    still aligns; a card whose bands are raw children rather than CardHeader/CardContent/
    CardFooter has nothing to align and is unaffected.

    The whole block is inside `@supports` because it is not decomposable: `grid-row: span 3`
    without a working `subgrid` would leave two empty tracks under every card.
  */
  @supports (grid-template-rows: subgrid) {
    .grid[data-align-rows] > * {
      grid-row: span 3;
      display: grid;
      grid-template-rows: subgrid;
      /* A subgrid inherits its parent's gap, so the grid's own `gap` would be re-applied
         BETWEEN a card's header, content and footer — measured at 16px of dead space per
         seam with `gap={4}`. The bands are the card's business; only the columns and the
         rows between cards get the grid gap. */
      row-gap: 0;
    }

    /* One level deeper — a Card inside a GridItem has to pass the tracks through, or the
       bands stop at the item and nothing is gained. `data-cascivo-card` is Card's published
       style hook (docs/STYLING-INTERNALS.md). */
    .grid[data-align-rows] > * > [data-cascivo-card] {
      grid-row: span 3;
      display: grid;
      grid-template-rows: subgrid;
      row-gap: 0;
    }
  }

  .grid-item {
    grid-column: span var(--_span, 1);

    /* The item stretches to the row (the grid's `align-items: stretch`), but a plain block
       container does not pass that height to its child — so a Card inside a spanning
       GridItem stopped at its own content height and left a visible hole beside a taller
       sibling (2026-08-08 report B). A grid container stretches its children by default,
       which is what an adopter already expects from the row. */
    display: grid;
    align-content: stretch;

    /* Responsive span — same per-tier fallback chain against the grid's inline size. */
    &[data-responsive] {
      @container (min-width: 30rem) {
        grid-column: span var(--_span-sm, var(--_span, 1));
      }
      @container (min-width: 40rem) {
        grid-column: span var(--_span-md, var(--_span-sm, var(--_span, 1)));
      }
      @container (min-width: 64rem) {
        grid-column: span var(--_span-lg, var(--_span-md, var(--_span-sm, var(--_span, 1))));
      }
      @container (min-width: 80rem) {
        grid-column: span
          var(--_span-xl, var(--_span-lg, var(--_span-md, var(--_span-sm, var(--_span, 1)))));
      }
    }
  }
}
